p.me:
\begin{array}{c|c|c}
\text{sign of } f' \text{ before } c \amp \text{sign of } f' \text{ after } c \amp \text{conclusion}\\
\hline
+ \amp - \amp \text{local maximum at } c\\
- \amp + \amp \text{local minimum at } c\\
+ \amp + \amp \text{no local extremum forced}\\
- \amp - \amp \text{no local extremum forced}
\end{array}

\begin{array}{ll}
\text{1.} \amp \text{Find all critical numbers of } f \text{ in } (a,b).\\
\text{2.} \amp \text{Evaluate } f \text{ at those critical numbers.}\\
\text{3.} \amp \text{Evaluate } f(a) \text{ and } f(b).\\
\text{4.} \amp \text{Compare the values.  The largest is the absolute maximum value.}\\
\amp \text{The smallest is the absolute minimum value.}
\end{array}
